    public static string VersionFor(int ordinal)=>$"usccss-g2-u06-source-rich-v2-{ordinal}";
    private static Entry? Find(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l)=>
        d.PackCode==MathematicsCurriculumPackRegistry.CommonCoreCode&&d.VersionCode=="CCSSM-2010"&&
        d.ContentVersion=="phase30-common-core-rich-content-v1"
          ?Entries.SingleOrDefault(x=>x.Code==l.LessonCode):null;
    public static bool IsTarget(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l)=>Find(d,l)!=null;
    private static void Guard(CanonicalLessonContentPackLesson lesson,Entry e)
    {
        if(lesson.SourceUrl!=e.Url||!string.Equals(lesson.CanonicalBodySha256,e.Sha,StringComparison.OrdinalIgnoreCase)||
           !lesson.OutcomeCodes.SequenceEqual(e.Outcomes))
            throw new InvalidOperationException($"G2 Unit6 original source identity drift ordinal{e.Ordinal}");
    }
    private static string[] Fields(CanonicalLessonContentPackTranslation t)=>
        [t.Explanation,t.KeyConceptsAndRules,t.WorkedExamples,t.StepByStepSolutions,t.CommonMistakes,t.QuickSummary];
    private static string[] Fields(CurriculumLessonContentTranslation t)=>
        [t.Explanation,t.KeyConceptsAndRules,t.WorkedExamples,t.StepByStepSolutions,t.CommonMistakes,t.QuickSummary];
    public static void Apply(CanonicalLessonContentPackDocument d)
    {
        foreach(var l in d.Lessons)
        {
            var e=Find(d,l);if(e==null)continue;
            Guard(l,e);var t=l.Translations.Single(x=>x.CultureCode=="en");
            if(Fields(t).SequenceEqual(e.After))continue;
            if(!Fields(t).SequenceEqual(e.Before))
               throw new InvalidOperationException($"G2 ordinal{e.Ordinal} lesson rich predecessor text drift");
            t.Explanation=e.After[0];t.KeyConceptsAndRules=e.After[1];t.WorkedExamples=e.After[2];
            t.StepByStepSolutions=e.After[3];t.CommonMistakes=e.After[4];t.QuickSummary=e.After[5];
        }
    }
    public static string GetExpectedContentVersion(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l,string previous)
    {
        var e=Find(d,l);return e==null?previous:VersionFor(e.Ordinal);
    }
    public static bool CanUpgradeExisting(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l,string prior)=>
        Find(d,l)!=null&&prior==CommonCoreRichContentCorrections.CorrectionContentVersion;
    public static void ValidateExistingBodyBeforeUpgrade(CanonicalLessonContentPackDocument d,CanonicalLessonContentPackLesson l,
        string prior,IReadOnlyCollection<CurriculumLessonContentTranslation> saved)
    {
        var e=Find(d,l)??throw new InvalidOperationException("Not a Grade2 Unit6 original source target");
        Guard(l,e);
        if(!CanUpgradeExisting(d,l,prior))throw new InvalidOperationException("Unexpected saved Grade2 Unit6 source predecessor version");
        if(saved.Count==0)return;
        if(saved.Count!=1||saved.Single().CultureCode!="en"||!Fields(saved.Single()).SequenceEqual(e.Before))
           throw new InvalidOperationException($"G2 ordinal{e.Ordinal} persisted source content drift");
    }
